class Solution { public long largestSquareArea(int[][] bottomLeft,int[][] topRight){long answer=0;for(int i=0;i<bottomLeft.length;i++)for(int j=i+1;j<bottomLeft.length;j++){int width=Math.min(topRight[i][0],topRight[j][0])-Math.max(bottomLeft[i][0],bottomLeft[j][0]);int height=Math.min(topRight[i][1],topRight[j][1])-Math.max(bottomLeft[i][1],bottomLeft[j][1]);if(width>0&&height>0){long side=Math.min(width,height);answer=Math.max(answer,side*side);}}return answer;} }
